function erpSidebarCss():string{return ':root{--o:#ff6702;--dark:#171b20;--ink:#27303b;--muted:#6e7781;--line:#e1e5e9;--bg:#f4f6f8;--sidebar:270px}*{box-sizing:border-box}.sidebar{position:fixed;z-index:1002;inset:0 auto 0 0;width:var(--sidebar);display:flex;flex-direction:column;padding:28px 18px 20px;background:var(--dark);color:#fff;box-shadow:8px 0 30px #11182014}.sidebar-brand{padding:0 12px 28px;border-bottom:1px solid #ffffff18}.sidebar-brand strong{display:block;font-size:22px}.sidebar-brand strong i,.mobile-topbar i{color:var(--o);font-style:normal}.sidebar-brand span{display:block;margin-top:6px;color:#aeb7c2;font-size:13px}.sidebar-nav{display:flex;flex-direction:column;gap:5px;padding:24px 0;overflow:auto;overscroll-behavior:contain}.sidebar-nav a{display:flex;align-items:center;gap:12px;padding:11px 13px;border-radius:9px;color:#d8dde3;text-decoration:none;font-weight:600}.sidebar-nav a:hover{background:#ffffff0d;color:#fff}.sidebar-nav a.active{background:var(--o);color:#fff}.nav-icon{width:22px;text-align:center}.nav-group{margin:4px 0}.nav-group-title{display:flex;align-items:center;gap:12px;padding:11px 13px;color:#fff;font-weight:750}.nav-submenu{display:flex;flex-direction:column;gap:3px;margin:0 0 7px 34px;padding-left:10px;border-left:1px solid #ffffff26}.sidebar-nav .nav-submenu a{padding:8px 11px;font-size:14px;font-weight:550}.sidebar-user{margin-top:auto;padding:18px 12px 0;border-top:1px solid #ffffff18}.sidebar-user small{display:block;color:#aeb7c2}.sidebar-user strong{display:block;margin:3px 0 12px}.sidebar-user a{color:#fff;text-decoration:none}.sidebar-overlay,.mobile-menu-btn,.mobile-topbar{display:none}@media(max-width:900px){body{padding-top:62px!important}body.menu-open{overflow:hidden}.mobile-topbar{display:flex;position:fixed;z-index:998;top:0;left:0;right:0;height:62px;background:#fff;border-bottom:1px solid var(--line);align-items:center;justify-content:space-between;padding:0 15px 0 62px;box-shadow:0 2px 12px #1118200d}.mobile-topbar strong{font-size:17px}.mobile-topbar span{max-width:42%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted);font-size:13px}.mobile-menu-btn{display:flex;position:fixed;z-index:1004;top:11px;left:12px;width:42px;height:40px;border:0;border-radius:10px;background:var(--dark);padding:10px;flex-direction:column;justify-content:center;gap:5px;cursor:pointer;box-shadow:0 2px 10px #0002}.mobile-menu-btn span{display:block;width:100%;height:2px;border-radius:2px;background:#fff;transition:.2s}.mobile-menu-btn.open span:nth-child(1){transform:translateY(7px) rotate(45deg)}.mobile-menu-btn.open span:nth-child(2){opacity:0}.mobile-menu-btn.open span:nth-child(3){transform:translateY(-7px) rotate(-45deg)}.sidebar{width:min(86vw,320px);transform:translateX(-105%);transition:transform .22s ease;padding-top:72px;box-shadow:10px 0 35px #0004}.sidebar.open{transform:translateX(0)}.sidebar-brand{display:none}.sidebar-nav{padding-top:0;flex:1}.sidebar-user{padding-bottom:max(8px,env(safe-area-inset-bottom))}.sidebar-overlay{display:block;position:fixed;z-index:1000;inset:0;background:#11182099;opacity:0;visibility:hidden;pointer-events:none;transition:.2s}.sidebar-overlay.show{opacity:1;visibility:visible;pointer-events:auto}.main,main,.wrap,.content{max-width:100%!important}.main{margin-left:0!important;padding-left:12px!important;padding-right:12px!important}table{max-width:100%}input,select,textarea,button{max-width:100%}.actions{max-width:100%}}';}
